words = ['timber', 'kelp', 'flint', 'harbor']
out = ""
for index in range(len(words)):
    piece = words[index]
    if index % 3 == 1:
        piece = piece.upper()
    if out == "":
        out = piece
    else:
        out = out + '-' + piece
print(out)

count = 0
for i in range(7):
    for j in range(7):
        if i < j:
            if (i + j) % 3 == 0:
                count = count + 1
print(count)

